mapper.select:
select c.*
from biz_iot_class_config c
where c.config_id = #{configId}

select * from biz_iot_group_student
where group_id = #{groupId}
order by sort_order asc, group_student_id asc

select * from biz_iot_group_student
where experiment_id = #{experimentId} and student_id = #{studentId}
limit 1

mapper.delete:
delete from biz_iot_group_student
where experiment_id = #{experimentId} and group_id in (
    select group_id from biz_iot_group where experiment_id = #{experimentId} and entry_year = #{entryYear} and class_code = #{classCode}
)

mapper.select:
select d.*, g.experiment_id from biz_iot_device d
join biz_iot_group g on g.group_id = d.group_id
join biz_iot_experiment e on e.experiment_id = g.experiment_id
where (
    concat(e.topic_prefix, '/', g.entry_year, '_', g.class_code, '/', e.activity_code, '/', g.group_code, '/', d.device_code, '/data') = #{topic}
    or concat(g.topic, '/device', d.device_code, '/data') = #{topic}
    or g.topic = #{topic}
)
  and e.status = '0' and g.status = '0' and d.status = '0'
limit 1

select count(*) from biz_lesson_assignment a
join biz_teacher_class tc on tc.dept_id = #{deptId} and tc.entry_year = a.entry_year and tc.class_code = a.class_code
where a.lesson_id = #{lessonId} and tc.user_id = #{userId}

select m.*, g.group_code, coalesce(d.device_code, 'data') as device_code from biz_iot_message m
join biz_iot_group g on g.group_id = m.group_id
left join biz_iot_device d on d.device_id = m.device_id
join biz_teacher_class tc on tc.entry_year = g.entry_year and tc.class_code = g.class_code
where m.experiment_id = #{experimentId} and tc.user_id = #{userId} and tc.dept_id = #{deptId}
order by m.received_at desc limit #{limit}

mapper.sql:
where m.experiment_id = #{experimentId}
and g.entry_year = #{entryYear}
and g.class_code = #{classCode}
and m.group_id = #{groupId}
and m.payload_type = #{payloadType}

    and (m.payload_text like concat('%', #{keyword}, '%')
         or coalesce(d.device_code, '') like concat('%', #{keyword}, '%')
         or m.topic like concat('%', #{keyword}, '%'))

mapper.select:
select m.*, g.group_code, coalesce(d.device_code, 'data') as device_code from biz_iot_message m

join biz_teacher_class tc on tc.entry_year = g.entry_year and tc.class_code = g.class_code

and tc.user_id = #{userId} and tc.dept_id = #{deptId}
order by m.received_at desc limit #{offset}, #{pageSize}

select count(*) from biz_iot_message m

join biz_teacher_class tc on tc.entry_year = g.entry_year and tc.class_code = g.class_code

and tc.user_id = #{userId} and tc.dept_id = #{deptId}

select e.* from biz_iot_event e join biz_iot_group g on g.group_id = e.group_id
join biz_teacher_class tc on tc.entry_year = g.entry_year and tc.class_code = g.class_code
where e.experiment_id = #{experimentId} and tc.user_id = #{userId} and tc.dept_id = #{deptId}
order by e.occurred_at desc limit #{limit}
